1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_MINIMUM_YEARS = 2;
23	const LOYALTY_DISCOUNT_RATE = 0.2;
24	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
25	
26	type Item = {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	};
32	
33	type Damage = {
34	  itemType: string;
35	  amount: number;
36	};
37	
38	type Incident = {
39	  cause: string;
40	  damages: Damage[];
41	};
42	
43	type Step = {
44	  op: string;
45	  items?: Item[];
46	  policy?: number;
47	  incident?: Incident;
48	};
49	
50	type Scenario = {
51	  customer: { yearsWithMHPCO: number };
52	  steps: Step[];
53	};
54	
55	type QuoteResult = {
56	  premium: number;
57	};
58	
59	type ClaimResult = {
60	  payout: number;
61	  remainingCap: number;
62	};
63	
64	type StepResult = QuoteResult | ClaimResult;
65	
66	type ScenarioOutput = {
67	  results: StepResult[];
68	};
69	
70	const isComponent = (item: Item): boolean =>
71	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
72	
73	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
74	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
75	  sameTypeItems.every(isComponent);
76	
77	const groupByType = (items: Item[]): Item[][] => {
78	  const groups = new Map<string, Item[]>();
79	  for (const item of items) {
80	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
81	  }
82	  return [...groups.values()];
83	};
84	
85	const basePremiumForItem = (item: Item): number =>
86	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
87	
88	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
89	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
90	  return sameTypeItems.reduce(
91	    (total, item) => total + basePremiumForItem(item),
92	    0,
93	  );
94	};
95	
96	const basePremiumForItems = (items: Item[]): number =>
97	  groupByType(items).reduce(
98	    (total, group) => total + basePremiumForGroup(group),
99	    0,
100	  );
101	
102	const amountAtRate = (
103	  basePremium: number,
104	  rate: number,
105	  applies?: boolean,
106	): number => (applies ? basePremium * rate : 0);
107	
108	const cursedSurcharge = (item: Item): number =>
109	  amountAtRate(basePremiumForItem(item), CURSED_SURCHARGE_RATE, item.cursed);
110	
111	const hasHighEnchantment = (item: Item): boolean =>
112	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
113	
114	const highEnchantmentSurcharge = (item: Item): number =>
115	  amountAtRate(
116	    basePremiumForItem(item),
117	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
118	    hasHighEnchantment(item),
119	  );
120	
121	const totalItemSurcharges = (items: Item[]): number =>
122	  items.reduce(
123	    (total, item) =>
124	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
125	    0,
126	  );
127	
128	const firstInsuranceSurcharge = (basePremium: number): number =>
129	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
130	
131	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
132	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS;
133	
134	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
135	  amountAtRate(
136	    basePremium,
137	    LOYALTY_DISCOUNT_RATE,
138	    isLoyalCustomer(yearsWithMHPCO),
139	  );
140	
141	const followUpDiscount = (basePremium: number, isFollowUp: boolean): number =>
142	  amountAtRate(basePremium, FOLLOW_UP_DISCOUNT_RATE, isFollowUp);
143	
144	const premiumBeforeProcessingFee = (
145	  items: Item[],
146	  yearsWithMHPCO: number,
147	  isFollowUp: boolean,
148	): number => {
149	  const basePremium = basePremiumForItems(items);
150	  return (
151	    basePremium +
152	    totalItemSurcharges(items) +
153	    firstInsuranceSurcharge(basePremium) -
154	    loyaltyDiscount(basePremium, yearsWithMHPCO) -
155	    followUpDiscount(basePremium, isFollowUp)
156	  );
157	};
158	
159	const isFollowUpQuote = (stepIndex: number): boolean => stepIndex > 0;
160	
161	const isClaimStep = (step: Step): boolean => step.op === "claim";
162	
163	const claimResultFor = (): ClaimResult => ({
164	  payout: 400,
165	  remainingCap: 1600,
166	});
167	
168	const quoteResultFor = (
169	  step: Step,
170	  yearsWithMHPCO: number,
171	  stepIndex: number,
172	): QuoteResult => ({
173	  premium: Math.ceil(
174	    premiumBeforeProcessingFee(
175	      step.items ?? [],
176	      yearsWithMHPCO,
177	      isFollowUpQuote(stepIndex),
178	    ) + PROCESSING_FEE,
179	  ),
180	});
181	
182	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
183	  results: scenario.steps.map((step, stepIndex) =>
184	    isClaimStep(step)
185	      ? claimResultFor()
186	      : quoteResultFor(step, scenario.customer.yearsWithMHPCO, stepIndex),
187	  ),
188	});
