const insuranceSumForItems = (items: Item[]): number =>
  items.reduce((total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);

const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimResultFor = (step: Step, steps: Step[]): ClaimResult => {
  const policyItems = steps[step.policy ?? 0].items ?? [];
  const cap = insuranceSumForItems(policyItems) * CAP_MULTIPLIER;
  const payout = payoutForDamage((step.incident?.damages ?? [])[0]);
  return { payout, remainingCap: cap - payout };
};

const FOLLOW_UP_DISCOUNT_RATE = 0.15;
const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;
const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
  sword: 1000,
  rune: 250,
};
